/*
 :helper
 Ini itu fungsi helper untuk testing data agar mudah melihat data test nya.
 Coba Jalankan Di Console Browser saat run dan panggil salah satu helper function seperti :
 - testInsufficient();
 - testNormal();
 - testOverweight();
 - testObesity();
 auto ngisi form lah intinya

*/
function testOverweight() { fill({ gender: "Male", age: 28, height: 1.75, weight: 82, family_history_with_overweight: "yes", favc: "yes", fcvc: 2, ncp: 3, caec: "Frequently", smoke: "no", ch2o: 1.5, scc: "no", faf: 1, tue: 4, calc: "Sometimes", mtrans: "Automobile" }) } function testNormal() { fill({ gender: "Female", age: 22, height: 1.65, weight: 58, family_history_with_overweight: "no", favc: "no", fcvc: 3, ncp: 3, caec: "Sometimes", smoke: "no", ch2o: 2, scc: "yes", faf: 2, tue: 2, calc: "Sometimes", mtrans: "Walking" }) } function testObesity() { fill({ gender: "Female", age: 35, height: 1.6, weight: 95, family_history_with_overweight: "yes", favc: "yes", fcvc: 1, ncp: 4, caec: "Always", smoke: "no", ch2o: 1, scc: "no", faf: 0, tue: 6, calc: "Frequently", mtrans: "Automobile" }) } function testInsufficient() { fill({ gender: "Male", age: 20, height: 1.8, weight: 52, family_history_with_overweight: "no", favc: "no", fcvc: 3, ncp: 3, caec: "no", smoke: "no", ch2o: 2.5, scc: "yes", faf: 3, tue: 1, calc: "no", mtrans: "Walking" }) } function fill(e) { Object.keys(e).forEach(t => { let c = document.getElementById(t); c && (c.value = e[t], c.dispatchEvent(new Event("change"))) }) }
